import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.apache.commons.text.StringEscapeUtils;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String format = req.getParameter("fmt");

        // Validate report type against whitelist
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // HTML-escape the format parameter for display
        String safeFormat = StringEscapeUtils.escapeHtml4(format);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Build query - sortCol is used for ORDER BY
            String baseQuery = "SELECT id, title, created_at, amount FROM reports "
                    + "WHERE report_type = ? AND date_range = ?";

            // Sort column applied dynamically - cannot use parameterized for ORDER BY
            String fullQuery = baseQuery + " ORDER BY " + sortCol;

            log.info("Executing report query for type=" + reportType + " range=" + dateRange);

            PreparedStatement stmt = conn.prepareStatement(fullQuery);
            stmt.setString(1, reportType);
            stmt.setString(2, dateRange);

            ResultSet rs = stmt.executeQuery();

            resp.setContentType("text/html; charset=UTF-8");
            PrintWriter out = resp.getWriter();
            out.println("<html><head><title>Report: " + safeFormat + "</title></head><body>");
            out.println("<table><tr><th>ID</th><th>Title</th><th>Date</th><th>Amount</th></tr>");

            while (rs.next()) {
                out.println("<tr><td>" + rs.getInt("id") + "</td>");
                out.println("<td>" + StringEscapeUtils.escapeHtml4(rs.getString("title")) + "</td>");
                out.println("<td>" + rs.getTimestamp("created_at") + "</td>");
                out.println("<td>" + rs.getBigDecimal("amount") + "</td></tr>");
            }

            out.println("</table></body></html>");
            out.flush();
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private boolean isValidReportType(String type) {
        if (type == null) return false;
        return type.matches("^(sales|inventory|payroll|expenses)$");
    }

    // Health check endpoint
    @Override
    protected void doHead(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setStatus(200);
    }
}
